/*
 * ⚠️  KAYAN-REPLICATE-ISOLATION-V1
 * LEGACY — REPLICATE-BASED, NOT PRODUCTION.
 *
 * This script references Replicate API. It must NEVER be used as
 * evidence that production video was generated by Replicate.
 *
 * Official production video pipeline:
 *   POST /api/video/generate
 *     → productionEngine.createProductionJob('VIDEO_GEN')
 *     → kayanGpuProvider.generateVideoKayanGpu()
 *     → GpuQueueService.enqueue('VIDEO_JOB')  [PostgreSQL]
 *     → queue-worker → KayanGPU Worker /jobs/video
 *     → LightX2V + HunyuanVideo 1.5 FP8 (A10G)
 *     → real MP4
 */
if (process.env.NODE_ENV === "production" && process.env.KAYAN_ALLOW_LEGACY_TESTS !== "1") { throw new Error("KAYAN-REPLICATE-ISOLATION-V1: this Replicate-based legacy script is blocked in production. Production video pipeline is KayanGPU only."); }

import { spawn } from "node:child_process";
import fs from "node:fs";
import path from "node:path";

function loadEnvFile() {
  const env = {};
  const envPaths = [".env", "/home/ubuntu/Nashash/.env"];
  for (const p of envPaths) {
    if (fs.existsSync(p)) {
      const content = fs.readFileSync(p, "utf-8");
      content.split("\n").forEach((line) => {
        const trimmed = line.trim();
        if (trimmed && !trimmed.startsWith("#") && trimmed.includes("=")) {
          const idx = trimmed.indexOf("=");
          const k = trimmed.substring(0, idx).trim();
          let v = trimmed.substring(idx + 1).trim();
          if ((v.startsWith('"') && v.endsWith('"')) || (v.startsWith("'") && v.endsWith("'"))) {
            v = v.slice(1, -1);
          }
          env[k] = v;
        }
      });
      break;
    }
  }
  return env;
}

const env = loadEnvFile();
const deepgramKey = env.DEEPGRAM_API_KEY || process.env.DEEPGRAM_API_KEY;
const replicateToken = env.REPLICATE_API_TOKEN || process.env.REPLICATE_API_TOKEN;
const videoModelVersion = env.REPLICATE_VIDEO_MODEL_VERSION || process.env.REPLICATE_VIDEO_MODEL_VERSION;

async function produceCinemaMasterpiece() {
  console.log("\n=======================================================");
  console.log("🎬 بدء دورة الإنتاج السينمائي الحقيقي (Full AI Pipeline)");
  console.log("=======================================================\n");

  const uploadsDir = path.resolve(process.cwd(), "uploads");
  const audioDir = path.join(uploadsDir, "audio");
  const rendersDir = path.join(uploadsDir, "renders");
  const tempDir = path.join(uploadsDir, "temp");

  [uploadsDir, audioDir, rendersDir, tempDir].forEach(d => {
    if (!fs.existsSync(d)) fs.mkdirSync(d, { recursive: true });
  });

  const dialogueText = "في عمق الصحراء العربية، تنطلق أولى رحلات استوديو كيان لإنتاج روائع السينما بالذكاء الاصطناعي.";
  const audioFilePath = path.join(audioDir, `voice_${Date.now()}.mp3`);

  // 1. Deepgram Real Arabic Audio Generation
  console.log("🗣️ [1/3] جاري توليد الصوت الحقيقي عبر Deepgram TTS...");
  const ttsRes = await fetch("https://api.deepgram.com/v1/speak?model=aura-asteria-en", {
    method: "POST",
    headers: {
      "Authorization": `Token ${deepgramKey}`,
      "Content-Type": "application/json"
    },
    body: JSON.stringify({ text: dialogueText })
  });

  if (!ttsRes.ok) {
    throw new Error(`Deepgram TTS failed: ${ttsRes.status} ${await ttsRes.text()}`);
  }

  const audioBuf = Buffer.from(await ttsRes.arrayBuffer());
  fs.writeFileSync(audioFilePath, audioBuf);
  console.log(`   ✅ تم إنتاج الصوت الحقيقي وحفظه (${(audioBuf.length / 1024).toFixed(1)} KB)`);

  // 2. Replicate Real AI Video Generation
  console.log("\n🎥 [2/3] جاري توليد لقطة الفيديو السينمائي بالذكاء الاصطناعي عبر Replicate...");
  console.log("   (جاري التواصل مع كروت الرسوميات GPU السحابية)...");

  const predRes = await fetch("https://api.replicate.com/v1/predictions", {
    method: "POST",
    headers: {
      "Authorization": `Bearer ${replicateToken}`,
      "Content-Type": "application/json",
      "Prefer": "wait=10"
    },
    body: JSON.stringify({
      version: videoModelVersion,
      input: {
        prompt: "Cinematic establishing drone shot of ancient Arab palace at sunset, golden hour light, photorealistic, 4k film still"
      }
    })
  });

  if (!predRes.ok) {
    throw new Error(`Replicate creation failed: ${predRes.status} ${await predRes.text()}`);
  }

  let prediction = await predRes.json();
  const predictionId = prediction.id;
  console.log(`   🆔 معرف مهمة الفيديو: ${predictionId} (الحالة: ${prediction.status})`);

  // Poll prediction until completed
  while (prediction.status !== "succeeded" && prediction.status !== "failed" && prediction.status !== "canceled") {
    await new Promise(r => setTimeout(r, 4000));
    const pollRes = await fetch(`https://api.replicate.com/v1/predictions/${predictionId}`, {
      headers: { "Authorization": `Bearer ${replicateToken}` }
    });
    prediction = await pollRes.json();
    process.stdout.write(`   ⏳ حالة معالجة الفيديو: ${prediction.status}...\r`);
  }

  console.log("\n");

  if (prediction.status !== "succeeded") {
    throw new Error(`Replicate prediction failed with status: ${prediction.status} - ${prediction.error}`);
  }

  let videoOutputUrl = prediction.output;
  if (Array.isArray(videoOutputUrl)) videoOutputUrl = videoOutputUrl[0];
  if (typeof videoOutputUrl === "object" && videoOutputUrl !== null) {
    videoOutputUrl = videoOutputUrl.video || videoOutputUrl.url || Object.values(videoOutputUrl)[0];
  }

  console.log(`   ✅ تم توليد لقطة الفيديو بنجاح!`);
  console.log(`   🔗 رابط الفيديو من المصدر: ${videoOutputUrl}`);

  // Download AI Video to local temp
  const localRawVideo = path.join(tempDir, `replicate_${Date.now()}.mp4`);
  const vidFetch = await fetch(videoOutputUrl);
  fs.writeFileSync(localRawVideo, Buffer.from(await vidFetch.arrayBuffer()));

  // 3. Final FFmpeg Rendering & Audio Muxing & Watermarking
  console.log("\n🎬 [3/3] جاري دمج الصوت البشري الحقيقي مع الفيديو السينمائي وحرق الترجمة والعلامة المائية...");
  const outputFileName = `kayan_ai_masterpiece_${Date.now()}.mp4`;
  const finalOutputPath = path.join(rendersDir, outputFileName);

  const ffmpegArgs = [
    "-y",
    "-i", localRawVideo,
    "-i", audioFilePath,
    "-filter_complex",
    "[0:v]drawtext=text='PRODUCED BY KAYAN AI PRODUCTIONS':x=w-tw-24:y=24:fontsize=16:fontcolor=white@0.85:box=1:boxcolor=black@0.5:boxborderw=5,drawtext=text='« في عمق الصحراء العربية، تنطلق أولى رحلات استوديو كيان »':x=(w-tw)/2:y=h-th-60:fontsize=20:fontcolor=yellow@0.95:box=1:boxcolor=black@0.6:boxborderw=6[v]",
    "-map", "[v]",
    "-map", "1:a",
    "-c:v", "libx264",
    "-c:a", "aac",
    "-shortest",
    "-pix_fmt", "yuv420p",
    finalOutputPath
  ];

  await new Promise((resolve, reject) => {
    const proc = spawn("ffmpeg", ffmpegArgs);
    proc.on("close", (code) => code === 0 ? resolve() : reject(new Error("FFmpeg exited with " + code)));
    proc.on("error", (err) => reject(err));
  });

  const stats = fs.statSync(finalOutputPath);
  const publicIp = await fetch("https://checkip.amazonaws.com").then(r => r.text()).then(t => t.trim()).catch(() => "localhost");

  console.log("\n=======================================================");
  console.log("🎉 اكتمل إنتاج الفيلم السينمائي الحقيقي بنجاح 100%!");
  console.log(`📦 اسم الملف: ${outputFileName} (الحجم: ${(stats.size / 1024).toFixed(1)} KB)`);
  console.log("=======================================================");
  console.log("👉 رابط المشاهدة المباشر في المتصفح:");
  console.log(`http://${publicIp}:3000/uploads/renders/${outputFileName}`);
  console.log("=======================================================\n");

  // Cleanup temp
  if (fs.existsSync(localRawVideo)) fs.unlinkSync(localRawVideo);
  process.exit(0);
}

produceCinemaMasterpiece().catch((err) => {
  console.error("\n❌ حدث خطأ أثناء الإنتاج:", err.message);
  process.exit(1);
});
